//! P22-016 / P22-025 — a checkable harness compatibility manifest.
//!
//! This module is the reader and validator for `contract/harness-compat.json`.
//! The file is hand-authored data derived from CLI source and config; it is
//! deliberately *not* generated by a tool, and it is deliberately not a
//! receipt. No client run is claimed anywhere in it.
//!
//! Three rules the validator enforces:
//!
//! * **Honest unknowns.** A field with no recorded evidence is JSON `null`.
//!   Every null must be explained by a reason in the top-level `unknowns`
//!   object; every reason must point at a field that really contains a null.
//!   A reason may be attached to a parent path to cover a whole group of
//!   observations (for example `clients.codex`).
//! * **Per-client verification.** Each client carries its own `verification`
//!   object. A client marked `not-live-verified` cannot claim a transcript or
//!   observed probe results, and its `last_seen` must be null.
//! * **Last seen is not live health.** The top-level `last_seen != live_health`
//!   flag must be true, and the manifest never records a live health verdict.
//!
//! The file is embedded at compile time so a missing or malformed manifest is
//! a build error. This module is self-contained (only `anyhow`/`serde_json`)
//! so it can be included directly from `tests/harness_compat_matrix.rs` via
//! `#[path]`.

use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail};
use serde_json::Value;

/// Schema tag this reader understands.
pub const SCHEMA: &str = "mn-harness-compat/1";
/// Manifest location, relative to the CLI crate root.
pub const MANIFEST_PATH: &str = "contract/harness-compat.json";
/// Clients that must be present: Codex/OpenCode first (P22-016), Claude/Cursor
/// and Zed as explicitly preview until verified (P22-025).
pub const REQUIRED_CLIENTS: &[&str] = &["codex", "opencode", "claude", "cursor"];
/// The embedded data file.
pub const MANIFEST_JSON: &str = include_str!("../contract/harness-compat.json");

/// Absolute path of the manifest, for diagnostics.
pub fn manifest_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join(MANIFEST_PATH)
}

/// Parse the embedded manifest.
pub fn load() -> Result<Value> {
    serde_json::from_str(MANIFEST_JSON)
        .with_context(|| format!("parse {}", manifest_path().display()))
}

/// Look up a dotted path. Keys in the manifest contain no `.` characters.
pub fn get<'a>(root: &'a Value, dotted: &str) -> Option<&'a Value> {
    let mut value = root;
    for key in dotted.split('.') {
        value = value.get(key)?;
    }
    Some(value)
}

fn collect_nulls(value: &Value, prefix: &str, out: &mut Vec<String>) {
    match value {
        Value::Null => out.push(prefix.to_owned()),
        Value::Object(map) => {
            for (key, child) in map {
                if prefix.is_empty() && key == "unknowns" {
                    continue;
                }
                let path = if prefix.is_empty() {
                    key.clone()
                } else {
                    format!("{prefix}.{key}")
                };
                collect_nulls(child, &path, out);
            }
        }
        _ => {}
    }
}

fn reason_for<'a>(unknowns: &'a Value, path: &str) -> Option<&'a str> {
    let mut candidate = path;
    loop {
        // `unknowns` keys are literal dotted strings, not nested objects: look
        // up the whole key first, then walk up to a parent (group) reason.
        if let Some(reason) = unknowns
            .get(candidate)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|reason| !reason.is_empty())
        {
            return Some(reason);
        }
        let index = candidate.rfind('.')?;
        candidate = &candidate[..index];
    }
}

fn non_empty_str<'a>(value: Option<&'a Value>, path: &str) -> Result<&'a str> {
    let text = value
        .with_context(|| format!("missing {path}"))?
        .as_str()
        .with_context(|| format!("{path} must be a string"))?;
    if text.trim().is_empty() {
        bail!("{path} must not be empty");
    }
    Ok(text)
}

/// Every null is explained, and every explanation refers to a real null.
pub fn validate_unknowns(manifest: &Value) -> Result<()> {
    let unknowns = get(manifest, "unknowns").context("missing `unknowns` object")?;
    let reasons = unknowns
        .as_object()
        .context("`unknowns` must be an object")?;

    let mut nulls = Vec::new();
    collect_nulls(manifest, "", &mut nulls);
    for path in &nulls {
        if reason_for(unknowns, path).is_none() {
            bail!("null field `{path}` has no reason in `unknowns`");
        }
    }

    for (key, reason) in reasons {
        let text = reason
            .as_str()
            .map(str::trim)
            .filter(|text| !text.is_empty())
            .with_context(|| format!("unknowns[{key}] must be a non-empty reason"))?;
        let target = get(manifest, key)
            .with_context(|| format!("unknowns key `{key}` does not resolve to a field: {text}"))?;
        let mut contained = Vec::new();
        collect_nulls(target, "", &mut contained);
        if contained.is_empty() {
            bail!("unknowns key `{key}` is a stale reason: the field is not null");
        }
    }
    Ok(())
}

/// `derived_from` paths with `scope: cli` must exist in this checkout.
pub fn validate_provenance(manifest: &Value) -> Result<()> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let entries = get(manifest, "derived_from")
        .and_then(Value::as_array)
        .context("missing `derived_from` array")?;
    if entries.is_empty() {
        bail!("`derived_from` must not be empty");
    }
    for (index, entry) in entries.iter().enumerate() {
        let path = non_empty_str(entry.get("path"), &format!("derived_from[{index}].path"))?;
        if entry.get("scope").and_then(Value::as_str) != Some("cli") {
            continue;
        }
        if !root.join(path).is_file() {
            bail!("derived_from[{index}].path does not exist in the CLI checkout: {path}");
        }
    }
    Ok(())
}

fn validate_client(manifest: &Value, name: &str, client: &Value) -> Result<()> {
    let at = format!("clients.{name}");
    for field in [
        "display_name",
        "status",
        "config_path",
        "config_format",
        "cli_managed_command",
        "profile",
        "registration_source",
        "handshake_source",
    ] {
        non_empty_str(client.get(field), &format!("{at}.{field}"))?;
    }

    let status = client["status"].as_str().expect("checked above");
    let verification = client
        .get("verification")
        .and_then(Value::as_object)
        .with_context(|| format!("{at}.verification must be an object"))?;
    let verified = status == "live-verified";
    if !verified && status != "not-live-verified" {
        bail!("{at}.status must be not-live-verified or live-verified, got {status:?}");
    }
    if verification.get("status").and_then(Value::as_str) != Some(status) {
        bail!("{at}.verification.status must match {at}.status");
    }
    for field in ["client_version", "server_version", "transcript"] {
        let value = verification
            .get(field)
            .with_context(|| format!("{at}.verification.{field} missing"))?;
        if !verified && !value.is_null() {
            bail!("{at}.verification.{field} cannot hold data while status is not-live-verified");
        }
        if verified && field == "transcript" && value.as_str().is_none_or(str::is_empty) {
            bail!("{at}.verification claims live-verified without a transcript");
        }
    }
    if !verified && !client.get("last_seen").is_some_and(Value::is_null) {
        bail!("{at}.last_seen must be null without a live verification");
    }

    let supported = get(manifest, "server.protocol.supported")
        .and_then(Value::as_array)
        .context("server.protocol.supported must be an array")?;
    let handshake = client
        .get("handshake_protocol_version")
        .with_context(|| format!("{at}.handshake_protocol_version missing"))?;
    if let Some(version) = handshake.as_str() {
        if !supported
            .iter()
            .any(|entry| entry.as_str() == Some(version))
        {
            bail!("{at}.handshake_protocol_version {version:?} is not a supported server revision");
        }
    } else if !handshake.is_null() {
        bail!("{at}.handshake_protocol_version must be a string or null");
    }

    let profile = client["profile"].as_str().expect("checked above");
    let counts = get(manifest, "server.profiles.tool_counts")
        .and_then(Value::as_object)
        .context("server.profiles.tool_counts must be an object")?;
    let expected_count = counts
        .get(profile)
        .and_then(Value::as_u64)
        .with_context(|| format!("{at}.profile {profile:?} has no published tool count"))?;

    let tools = client
        .get("discovered_tools")
        .and_then(Value::as_object)
        .with_context(|| format!("{at}.discovered_tools must be an object"))?;
    if tools.get("expected_from_profile").and_then(Value::as_str) != Some(profile) {
        bail!("{at}.discovered_tools.expected_from_profile must match the client profile");
    }
    let declared = tools
        .get("expected_tool_count")
        .and_then(Value::as_u64)
        .with_context(|| format!("{at}.discovered_tools.expected_tool_count missing"))?;
    if declared != expected_count {
        bail!("{at} declares {declared} tools, profile {profile} publishes {expected_count}");
    }
    let ref_path = format!("server.profiles.{profile}_tools");
    let referenced = tools
        .get("expected_tools_ref")
        .and_then(Value::as_str)
        .with_context(|| format!("{at}.discovered_tools.expected_tools_ref missing"))?;
    let names = get(manifest, referenced)
        .and_then(Value::as_array)
        .with_context(|| {
            format!("{at}.discovered_tools.expected_tools_ref does not resolve: {referenced}")
        })?;
    if referenced != ref_path {
        bail!("{at}.discovered_tools.expected_tools_ref must be {ref_path:?}");
    }
    if names.len() as u64 != expected_count {
        bail!(
            "{ref_path} has {} names, expected {expected_count}",
            names.len()
        );
    }
    let mut sorted = Vec::new();
    for name in names {
        let tool = name
            .as_str()
            .with_context(|| format!("{ref_path} must contain strings"))?;
        sorted.push(tool);
    }
    let mut copy = sorted.clone();
    copy.sort_unstable();
    copy.dedup();
    if copy != sorted {
        bail!("{ref_path} must be sorted and unique (tools/list is deterministic)");
    }
    if !verified && !tools.get("observed").is_some_and(Value::is_null) {
        bail!("{at}.discovered_tools.observed must be null without a live run");
    }

    let safe = client
        .get("safe_retrieval")
        .and_then(Value::as_object)
        .with_context(|| format!("{at}.safe_retrieval must be an object"))?;
    let denial = client
        .get("expected_denial")
        .and_then(Value::as_object)
        .with_context(|| format!("{at}.expected_denial must be an object"))?;
    let safe_tool = non_empty_str(safe.get("tool"), &format!("{at}.safe_retrieval.tool"))?;
    let denial_tool = non_empty_str(denial.get("tool"), &format!("{at}.expected_denial.tool"))?;
    if Some(safe_tool) != get(manifest, "server.probes.safe_retrieval.tool").and_then(Value::as_str)
    {
        bail!("{at}.safe_retrieval.tool must be the canonical safe retrieval probe");
    }
    if Some(denial_tool)
        != get(manifest, "server.probes.expected_denial.tool").and_then(Value::as_str)
    {
        bail!("{at}.expected_denial.tool must be the canonical expected-denial probe");
    }
    if safe_tool == denial_tool {
        bail!("{at}: the safe retrieval probe and the expected denial must be different tools");
    }
    if !sorted.contains(&safe_tool) || !sorted.contains(&denial_tool) {
        bail!("{at}: a probe names a tool outside the {profile} profile surface");
    }
    if !safe.get("arguments").is_some_and(Value::is_object) {
        bail!("{at}.safe_retrieval.arguments must be an object");
    }
    non_empty_str(
        denial.get("precondition"),
        &format!("{at}.expected_denial.precondition"),
    )?;
    if denial.get("expect_is_error") != Some(&Value::Bool(true)) {
        bail!("{at}.expected_denial.expect_is_error must be true");
    }
    let contains = denial
        .get("expect_text_contains")
        .and_then(Value::as_array)
        .with_context(|| format!("{at}.expected_denial.expect_text_contains missing"))?;
    if contains.is_empty()
        || contains
            .iter()
            .any(|value| value.as_str().is_none_or(str::is_empty))
    {
        bail!("{at}.expected_denial.expect_text_contains must be a non-empty string list");
    }
    if !verified {
        for (label, value) in [
            ("safe_retrieval.observed", safe.get("observed")),
            ("expected_denial.observed", denial.get("observed")),
        ] {
            if !value.is_some_and(Value::is_null) {
                bail!("{at}.{label} must be null without a live run");
            }
        }
    }
    Ok(())
}

/// Full validation: schema, health semantics, provenance, unknowns and every
/// required client. Call this from tests and from `mcp doctor`-style consumers.
pub fn validate(manifest: &Value) -> Result<()> {
    if non_empty_str(manifest.get("schema"), "schema")? != SCHEMA {
        bail!("unsupported manifest schema, expected {SCHEMA}");
    }
    if manifest.get("generated") != Some(&Value::Bool(false)) {
        bail!("`generated` must be false: this file is hand-authored data");
    }
    if manifest.get("last_seen != live_health") != Some(&Value::Bool(true)) {
        bail!("`last_seen != live_health` must be explicitly true");
    }
    let health = get(manifest, "health_semantics")
        .and_then(Value::as_object)
        .context("missing `health_semantics` object")?;
    non_empty_str(health.get("assertion"), "health_semantics.assertion")?;
    if !health.get("live_health").is_some_and(Value::is_null) {
        bail!("health_semantics.live_health must be null: last_seen is not a health probe");
    }

    validate_unknowns(manifest)?;
    validate_provenance(manifest)?;

    let supported = get(manifest, "server.protocol.supported")
        .and_then(Value::as_array)
        .context("server.protocol.supported must be an array")?;
    for version in ["2025-11-25", "2026-07-28"] {
        if !supported
            .iter()
            .any(|value| value.as_str() == Some(version))
        {
            bail!("server.protocol.supported is missing {version}");
        }
    }

    let clients = get(manifest, "clients")
        .and_then(Value::as_object)
        .context("missing `clients` object")?;
    for name in REQUIRED_CLIENTS {
        let client = clients
            .get(*name)
            .with_context(|| format!("missing required client {name:?}"))?;
        validate_client(manifest, name, client)
            .with_context(|| format!("client {name:?} failed manifest validation"))?;
    }
    Ok(())
}
